{
  "scenarios": [
    {
      "id": "T1-POST-001",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "positive",
      "purpose": "Fornecer um registro representável, com identificadores preservando zeros e textos curtos.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [
            {
              "transactionId": "0000000000000001",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "T1",
              "description": "Entrada",
              "amount": 1.25,
              "merchantId": "000000001",
              "merchantName": "M",
              "merchantCity": "C",
              "merchantZip": "00000",
              "cardNumber": "0000000000000001",
              "originalTimestamp": "2022-01-01",
              "processingTimestamp": ""
            }
          ]
        }
      },
      "expectedFromContract": {
        "transport": "O corpo satisfaz o schema; textos curtos são preenchidos à direita com espaços.",
        "on200": {
          "required": ["transactions", "rejects", "processedCount", "rejectedCount"],
          "processedCount": 1,
          "transactionsItemsSchema": "#/components/schemas/Transaction",
          "rejectsItemsSchema": "#/components/schemas/RejectedTransaction",
          "rules": [
            "O registro pode ser aceito ou rejeitado conforme as dependências persistentes.",
            "Se houver rejeição, returnCode é 4.",
            "Se aceito, processingTimestamp é substituído pelo timestamp corrente no formato YYYY-MM-DD-HH.MM.SS.hh0000."
          ]
        },
        "on500": "O envelope segue ExecutionFailure; efeitos anteriores podem permanecer."
      },
      "limitations": [
        "Os valores são entradas candidatas, não evidência de cartões, contas ou categorias existentes.",
        "Não é possível determinar aceitação, motivo de rejeição ou saldos sem dependências ambientais.",
        "A entrega de falhas depende do runtime e do serviço CEE3ABD."
      ]
    },
    {
      "id": "T1-POST-002",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "boundary",
      "purpose": "Exercitar o array de entrada vazio permitido pelo contrato.",
      "request": {"bodyKind": "json", "bodyJson": {"dailyTransactions": []}},
      "expectedFromContract": {
        "on200": {
          "transactions": [],
          "rejects": [],
          "processedCount": 0,
          "rejectedCount": 0,
          "rules": ["Não há atribuição explícita de returnCode no ramo sem rejeições."]
        },
        "on500": "Falhas fatais de abertura ou fechamento podem produzir ExecutionFailure."
      },
      "limitations": [
        "Entrada vazia não elimina as precondições de arquivos.",
        "TRANFILE é aberto OUTPUT; não se garante preservação de conteúdo anterior."
      ]
    },
    {
      "id": "T1-POST-003",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "boundary",
      "purpose": "Representar o limite inferior de Amount e strings vazias onde não há minLength.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [
            {
              "transactionId": "",
              "typeCode": "",
              "categoryCode": "0000",
              "source": "",
              "description": "",
              "amount": -999999999.99,
              "merchantId": "000000000",
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": "",
              "filler": ""
            }
          ]
        }
      },
      "expectedFromContract": {
        "transport": "O registro é representável pelo schema; valor negativo e strings vazias nesses campos não constituem erro de transporte.",
        "on200": {
          "required": ["transactions", "rejects", "processedCount", "rejectedCount"],
          "processedCount": 1,
          "transactionsItemsSchema": "#/components/schemas/Transaction",
          "rejectsItemsSchema": "#/components/schemas/RejectedTransaction",
          "rules": [
            "Se aceito, o amount negativo é somado, ainda negativo, a currentCycleDebit.",
            "Se rejeitado, o registro preserva filler e recebe uma razão contratual; returnCode é 4."
          ]
        },
        "on500": "Falhas fatais seguem ExecutionFailure, sem garantia de desfazer efeitos."
      },
      "limitations": [
        "Não se presume existência de referência para cartão preenchido com espaços.",
        "Overflow aritmético não é especificado; o limite de transporte não garante execução aritmética segura."
      ]
    },
    {
      "id": "T1-POST-004",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "negative",
      "purpose": "Omitir a propriedade obrigatória dailyTransactions.",
      "request": {"bodyKind": "json", "bodyJson": {}},
      "expectedFromContract": {
        "status": 400,
        "reason": "O objeto não satisfaz required: [dailyTransactions].",
        "responseBody": "Não há schema de payload definido para TransportError."
      },
      "limitations": ["Não se infere motivo COBOL, mensagem ou envelope de erro."]
    },
    {
      "id": "T1-POST-005",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "negative",
      "purpose": "Fornecer null em lugar do array obrigatório.",
      "request": {"bodyKind": "json", "bodyJson": {"dailyTransactions": null}},
      "expectedFromContract": {
        "status": 400,
        "reason": "dailyTransactions deve ser array e não admite null.",
        "responseBody": "Não há schema de payload definido para TransportError."
      },
      "limitations": ["O cenário cobre transporte, não validação de registros pelo programa."]
    },
    {
      "id": "T1-POST-006",
      "operation": {"method": "POST", "path": "/transaction-postings"},
      "category": "negative",
      "purpose": "Fornecer um item sem os campos obrigatórios de Transaction.",
      "request": {"bodyKind": "json", "bodyJson": {"dailyTransactions": [{}]}},
      "expectedFromContract": {
        "status": 400,
        "reason": "O item não satisfaz os campos required de Transaction.",
        "responseBody": "Não há schema de payload definido para TransportError."
      },
      "limitations": ["Não se infere ordem de detecção dos campos ausentes."]
    },
    {
      "id": "T1-INTEREST-001",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "positive",
      "purpose": "Invocar a geração com o prefixo de dez caracteres exemplificado no contrato.",
      "request": {"bodyKind": "json", "bodyJson": {"transactionIdPrefix": "2022071800"}},
      "expectedFromContract": {
        "on200": {
          "required": ["transactions"],
          "transactionsItemsSchema": "#/components/schemas/Transaction",
          "rules": [
            "IDs gerados concatenam o prefixo com sufixo de seis dígitos iniciado em 000001.",
            "A geração não posta nem mescla transações e não modifica saldos de categoria.",
            "O último account não é reescrito pelo fluxo normal de EOF."
          ]
        },
        "on500": "Falhas fatais seguem ExecutionFailure; saídas e reescritas anteriores podem existir."
      },
      "limitations": [
        "Quantidade, valores e cartões das transações dependem exclusivamente de arquivos ambientais.",
        "Não é possível selecionar taxas, contas ou grupos pelo request.",
        "Overflow de sufixo não tem comportamento tratado; leituras por chave alternativa dependem da configuração do runtime."
      ]
    },
    {
      "id": "T1-INTEREST-002",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "positive",
      "purpose": "Representar prefixo não numérico com espaços, sem interpretá-lo como data.",
      "request": {"bodyKind": "json", "bodyJson": {"transactionIdPrefix": "AB CD"}},
      "expectedFromContract": {
        "transport": "Caracteres arbitrários e espaços são permitidos; o prefixo é preenchido à direita até dez caracteres.",
        "on200": {
          "required": ["transactions"],
          "transactionsItemsSchema": "#/components/schemas/Transaction",
          "rules": [
            "IDs gerados usam todos os dez caracteres do prefixo preenchido e o sufixo sequencial.",
            "Ambos os timestamps gerados usam o formato corrente YYYY-MM-DD-HH.MM.SS.hh0000."
          ]
        },
        "on500": "O contrato declara ExecutionFailure para execução fatal."
      },
      "limitations": [
        "Não se garante geração de qualquer transação.",
        "A requisição não controla as dependências persistentes nem o relógio."
      ]
    },
    {
      "id": "T1-INTEREST-003",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "boundary",
      "purpose": "Exercitar o prefixo vazio, permitido pela ausência de minLength.",
      "request": {"bodyKind": "json", "bodyJson": {"transactionIdPrefix": ""}},
      "expectedFromContract": {
        "transport": "A string vazia é válida e é preenchida com dez espaços.",
        "on200": {
          "required": ["transactions"],
          "transactionsItemsSchema": "#/components/schemas/Transaction",
          "rules": ["Se houver transações geradas, seus IDs começam com os dez espaços do prefixo."]
        },
        "on500": "O contrato declara ExecutionFailure para execução fatal."
      },
      "limitations": [
        "Prefixo vazio não significa entrada TCATBALF vazia.",
        "Nenhum caso de taxa zero, taxa negativa ou mudança de conta pode ser forçado por esse request."
      ]
    },
    {
      "id": "T1-INTEREST-004",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "negative",
      "purpose": "Ultrapassar em um caractere o limite de comprimento do prefixo.",
      "request": {"bodyKind": "json", "bodyJson": {"transactionIdPrefix": "12345678901"}},
      "expectedFromContract": {
        "status": 400,
        "reason": "transactionIdPrefix excede maxLength: 10.",
        "responseBody": "TransportError não define payload."
      },
      "limitations": ["Não se presume truncamento de entradas acima do limite."]
    },
    {
      "id": "T1-INTEREST-005",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "negative",
      "purpose": "Omitir o prefixo obrigatório.",
      "request": {"bodyKind": "json", "bodyJson": {}},
      "expectedFromContract": {
        "status": 400,
        "reason": "transactionIdPrefix é obrigatório.",
        "responseBody": "TransportError não define payload."
      },
      "limitations": ["Não há valor padrão contratual para propriedade ausente."]
    },
    {
      "id": "T1-INTEREST-006",
      "operation": {"method": "POST", "path": "/interest-transaction-generations"},
      "category": "negative",
      "purpose": "Fornecer prefixo numérico JSON em vez de string.",
      "request": {"bodyKind": "json", "bodyJson": {"transactionIdPrefix": 2022071800}},
      "expectedFromContract": {
        "status": 400,
        "reason": "transactionIdPrefix deve ser string.",
        "responseBody": "TransportError não define payload."
      },
      "limitations": ["Não há coerção de number para string declarada."]
    },
    {
      "id": "T1-REPORT-001",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "positive",
      "purpose": "Fornecer um detalhe com prefixo de processamento dentro do intervalo inclusivo.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [
            {
              "transactionId": "0000000000000001",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "T1",
              "description": "Detalhe",
              "amount": 1.25,
              "merchantId": "000000001",
              "merchantName": "M",
              "merchantCity": "C",
              "merchantZip": "00000",
              "cardNumber": "0000000000000001",
              "originalTimestamp": "",
              "processingTimestamp": "2022-01-01"
            }
          ],
          "dateParameterRecords": ["2022-01-01 2022-01-01"]
        }
      },
      "expectedFromContract": {
        "transport": "O corpo é representável; a comparação de datas usa caracteres e inclui os extremos.",
        "on200": {
          "required": ["lines"],
          "linesItems": {"type": "string", "minLength": 133, "maxLength": 133},
          "rules": [
            "O primeiro detalhe emite quatro registros de cabeçalho.",
            "Não ocorre ordenação da entrada.",
            "Os totais seguem o controle de fluxo de EOF descrito, não uma agregação corrigida."
          ]
        },
        "on500": "Chaves de lookup desconhecidas ou falhas fatais de I/O podem produzir ExecutionFailure; saída parcial pode existir."
      },
      "limitations": [
        "Não se pressupõe existência das chaves em CARDXREF, TRANTYPE ou TRANCATG.",
        "Não se fixa conteúdo literal das linhas nem totais; o buffer de EOF depende do runtime.",
        "Nenhuma chamada HTTP foi executada."
      ]
    },
    {
      "id": "T1-REPORT-002",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "boundary",
      "purpose": "Representar EOF imediato em DATEPARM com ambos os arrays vazios.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {"transactions": [], "dateParameterRecords": []}
      },
      "expectedFromContract": {
        "on200": {
          "required": ["lines"],
          "linesItems": {"type": "string", "minLength": 133, "maxLength": 133},
          "rules": ["EOF em DATEPARM encerra o processamento sem ler transações."]
        },
        "on500": "Falhas fatais de abertura ou fechamento continuam possíveis e seguem ExecutionFailure."
      },
      "limitations": ["Arrays vazios não dispensam os arquivos e o runtime exigidos pelo contrato."]
    },
    {
      "id": "T1-REPORT-003",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "boundary",
      "purpose": "Representar um registro DATEPARM vazio, distinto de um array DATEPARM vazio.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {"transactions": [], "dateParameterRecords": [""]}
      },
      "expectedFromContract": {
        "transport": "A string vazia é válida e é preenchida à direita até 80 caracteres.",
        "on200": {
          "required": ["lines"],
          "linesItems": {"type": "string", "minLength": 133, "maxLength": 133},
          "rules": ["As posições 1-10 e 12-21 do primeiro registro fornecem os limites; não há validação de calendário."]
        },
        "on500": "O contrato declara ExecutionFailure para execução fatal."
      },
      "limitations": [
        "O comportamento do buffer de transações vazio depende do runtime.",
        "Não se promete array lines vazio nem totais normalizados."
      ]
    },
    {
      "id": "T1-REPORT-004",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "positive",
      "purpose": "Representar intervalo invertido, separador arbitrário e um registro DATEPARM adicional ignorado.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": ["2022-12-31X2022-01-01", "IGNORADO"]
        }
      },
      "expectedFromContract": {
        "transport": "Não há rejeição por ordem das datas, formato de calendário ou separador.",
        "on200": {
          "required": ["lines"],
          "linesItems": {"type": "string", "minLength": 133, "maxLength": 133},
          "rules": [
            "Somente o primeiro registro DATEPARM é lido.",
            "A posição 11 é ignorada.",
            "O segundo registro não determina o intervalo."
          ]
        },
        "on500": "O contrato declara ExecutionFailure para execução fatal."
      },
      "limitations": [
        "Entrada de transações vazia não exercita detalhes nem agrupamento.",
        "Não se infere conteúdo de relatório a partir de um buffer vazio dependente do runtime."
      ]
    },
    {
      "id": "T1-REPORT-005",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "negative",
      "purpose": "Omitir dateParameterRecords, embora transactions esteja presente.",
      "request": {"bodyKind": "json", "bodyJson": {"transactions": []}},
      "expectedFromContract": {
        "status": 400,
        "reason": "dateParameterRecords é obrigatório.",
        "responseBody": "TransportError não define payload."
      },
      "limitations": ["Propriedade ausente não equivale contratualmente a EOF de DATEPARM."]
    },
    {
      "id": "T1-REPORT-006",
      "operation": {"method": "POST", "path": "/transaction-reports"},
      "category": "negative",
      "purpose": "Fornecer um item numérico em dateParameterRecords.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {"transactions": [], "dateParameterRecords": [20220101]}
      },
      "expectedFromContract": {
        "status": 400,
        "reason": "Cada item de dateParameterRecords deve ser string.",
        "responseBody": "TransportError não define payload."
      },
      "limitations": ["Não há conversão contratual de números em registros DATEPARM."]
    }
  ]
}
